    console.log("  id:", inv.id);
    console.log("  invoiceNumber:", inv.invoiceNumber);
    console.log("  amountExcludingVatCurrency:", inv.amountExcludingVatCurrency);
    console.log("  amountCurrency:", inv.amountCurrency);
