      lines.forEach((l: any, i: number) => {
        console.log(`  Line ${i}: desc=${l.description}, count=${l.count}, price=${l.unitPriceExcludingVatCurrency}, vatType=${l.vatType?.id}(${l.vatType?.percentage}%)`);
